proc stepEncLcnApAccess*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnApAccess](src)
  var n = 0
  if x.methods.isSome:
    inc n
  if x.publish_events.isSome:
    inc n
  if x.subscribe_events.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.methods.isSome:
    node.entries[k].key = cbor("methods")
    let a1 = newCborArray(x.methods.get.len)
    node.entries[k].value = a1
    for i2 in 0 ..< x.methods.get.len:
      w.later(stepEncLcnApDecl, addr x.methods.get[i2], addr a1.items[i2])
    inc k
  if x.publish_events.isSome:
    node.entries[k].key = cbor("publish_events")
    let a5 = newCborArray(x.publish_events.get.len)
    node.entries[k].value = a5
    for i6 in 0 ..< x.publish_events.get.len:
      w.later(stepEncLcnApDecl, addr x.publish_events.get[i6], addr a5.items[i6])
    inc k
  if x.subscribe_events.isSome:
    node.entries[k].key = cbor("subscribe_events")
    let a9 = newCborArray(x.subscribe_events.get.len)
    node.entries[k].value = a9
    for i10 in 0 ..< x.subscribe_events.get.len:
      w.later(stepEncLcnApDecl, addr x.subscribe_events.get[i10], addr a9.items[i10])
    inc k

proc stepDecLcnApAccess*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnApAccess](dst)
  r[] = LcnApAccess()
  let f3 = v.lookup("methods")
  if f3.isSome:
    r.methods = Opt.some(default(seq[LcnApDecl]))
    r.methods.get.setLen(f3.get.items.len)
    for i4 in 0 ..< f3.get.items.len:
      w.later(stepDecLcnApDecl, f3.get.items[i4], addr r.methods.get[i4])
  let f7 = v.lookup("publish_events")
  if f7.isSome:
    r.publish_events = Opt.some(default(seq[LcnApDecl]))
    r.publish_events.get.setLen(f7.get.items.len)
    for i8 in 0 ..< f7.get.items.len:
      w.later(stepDecLcnApDecl, f7.get.items[i8], addr r.publish_events.get[i8])
  let f11 = v.lookup("subscribe_events")
  if f11.isSome:
    r.subscribe_events = Opt.some(default(seq[LcnApDecl]))
    r.subscribe_events.get.setLen(f11.get.items.len)
    for i12 in 0 ..< f11.get.items.len:
      w.later(stepDecLcnApDecl, f11.get.items[i12], addr r.subscribe_events.get[i12])

proc toCbor*(x: LcnApAccess): CborValue =
  runEnc(stepEncLcnApAccess, addr x)

proc fromChecked*(T: type LcnApAccess, v: CborValue): LcnApAccess =
  var r: LcnApAccess
  runDec(stepDecLcnApAccess, v, addr r)
  r

proc stepEncLcnApAction*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnApAction](src)
  case x.kind
  of LcnApActionKind.Call:
    dst[] = cbor("call")
  of LcnApActionKind.Discover:
    dst[] = cbor("discover")
  of LcnApActionKind.Establish_route:
    dst[] = cbor("establish-route")
  of LcnApActionKind.Publish_event:
    dst[] = cbor("publish-event")
  of LcnApActionKind.Renew_route:
    dst[] = cbor("renew-route")
  of LcnApActionKind.Subscribe_event:
    dst[] = cbor("subscribe-event")

proc stepDecLcnApAction*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnApAction](dst)
  case generatedSchema().arm("lcn.ap_action#", v)
  of 0:
    r[] = LcnApAction(kind: LcnApActionKind.Call)
  of 1:
    r[] = LcnApAction(kind: LcnApActionKind.Discover)
  of 2:
    r[] = LcnApAction(kind: LcnApActionKind.Renew_route)
  of 3:
    r[] = LcnApAction(kind: LcnApActionKind.Publish_event)
  of 4:
    r[] = LcnApAction(kind: LcnApActionKind.Establish_route)
  of 5:
    r[] = LcnApAction(kind: LcnApActionKind.Subscribe_event)
  else:
    raiseAssert "a checked value selects a known arm"

proc toCbor*(x: LcnApAction): CborValue =
  runEnc(stepEncLcnApAction, addr x)

proc fromChecked*(T: type LcnApAction, v: CborValue): LcnApAction =
  var r: LcnApAction
  runDec(stepDecLcnApAction, v, addr r)
  r

