proc stepEncLcnApInspect*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnApInspect](src)
  var n = 2
  if x.audit.isSome:
    inc n
  if x.grants.isSome:
    inc n
  if x.policy_changes.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.audit.isSome:
    node.entries[k].key = cbor("audit")
    w.later(stepEncLcnApTarget, addr x.audit.get, addr node.entries[k].value)
    inc k
  if x.grants.isSome:
    node.entries[k].key = cbor("grants")
    w.later(stepEncLcnApTarget, addr x.grants.get, addr node.entries[k].value)
    inc k
  node.entries[k].key = cbor("kind")
  node.entries[k].value = cbor("inspect")
  inc k
  if x.policy_changes.isSome:
    node.entries[k].key = cbor("policy_changes")
    node.entries[k].value = cbor(true)
    inc k
  node.entries[k].key = cbor("subject")
  w.later(stepEncLcnApSubject, addr x.subject, addr node.entries[k].value)
  inc k

proc stepDecLcnApInspect*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnApInspect](dst)
  r[] = LcnApInspect()
  let f27 = v.lookup("audit")
  if f27.isSome:
    r.audit = Opt.some(default(LcnApTarget))
    w.later(stepDecLcnApTarget, f27.get, addr r.audit.get)
  let f28 = v.lookup("grants")
