proc stepEncLcnAppPolicyARCapabilityAuthorityMap*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnAppPolicyARCapabilityAuthorityMap](src)
  var n = 3
  if x.evaluation_deadline_ms.isSome:
    inc n
  if x.recovery.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  node.entries[k].key = cbor("authority")
  node.entries[k].value = encLcnAppInstanceId(x.authority)
  inc k
  if x.evaluation_deadline_ms.isSome:
    node.entries[k].key = cbor("evaluation_deadline_ms")
    node.entries[k].value = cbor(uint64(x.evaluation_deadline_ms.get))
    inc k
  node.entries[k].key = cbor("kind")
  node.entries[k].value = cbor("capability-authority")
  inc k
  node.entries[k].key = cbor("policy")
  w.later(stepEncLcnAuthorityPolicy, addr x.policy, addr node.entries[k].value)
  inc k
  if x.recovery.isSome:
    node.entries[k].key = cbor("recovery")
    node.entries[k].value = cbor(x.recovery.get)
    inc k

