proc stepEncLcnAppPolicy*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnAppPolicy](src)
  case x.kind
  of LcnAppPolicyKind.Allow_all:
    w.later(stepEncLcnAppPolicyARAllowAllMap, addr x.arm_Allow_all, addr dst[])
  of LcnAppPolicyKind.Capability_authority:
    w.later(stepEncLcnAppPolicyARCapabilityAuthorityMap, addr x.arm_Capability_authority, addr dst[])

proc stepDecLcnAppPolicy*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnAppPolicy](dst)
  case generatedSchema().arm("lcn.app_policy#", v)
  of 0:
    r[] = LcnAppPolicy(kind: LcnAppPolicyKind.Allow_all)
    w.later(stepDecLcnAppPolicyARAllowAllMap, v, addr r.arm_Allow_all)
  of 1:
    r[] = LcnAppPolicy(kind: LcnAppPolicyKind.Capability_authority)
    w.later(stepDecLcnAppPolicyARCapabilityAuthorityMap, v, addr r.arm_Capability_authority)
  else:
    raiseAssert "a checked value selects a known arm"

